import { html } from "../../../../html.js";
import { useState } from "/prototype/vendor/preact-hooks.js";
import { Dialog, Icon, StatusPill, Tabs } from "../../ui/index.js";
import PageVariants from "../../ui/PageVariants.js";
import { agents, audits, conversations } from "./data.js";

const notify=(set,text)=>{set(text);setTimeout(()=>set(''),2400)};
const state=a=>a.status==='online'?'running':a.status==='paused'?'held':'error';
function Toast({text}){return text&&html`<div class="p-agents-toast" role="status">${text}</div>`}
function Action({children,onClick,primary=false}){return html`<button class=${`p-agents-action ${primary?'primary':''}`} onClick=${onClick}>${children}</button>`}
function CreateDialog({close,done}){const [step,setStep]=useState(1);return html`<${Dialog} onClose=${close}><div class="p-agents-dialog"><p>ATTACH AGENT · ${step} / 2</p><h2>${step===1?'Choose a device':'Confirm operating envelope'}</h2>${step===1?html`<div class="p-agents-device-choice"><button onClick=${()=>setStep(2)}><b>dev-mbp</b><small>Online · daemon 0.8.1 · local</small></button><button onClick=${()=>setStep(2)}><b>ci-west</b><small>Online · daemon 0.8.1 · cloud</small></button></div>`:html`<div class="p-agents-form"><label>Agent name<input value="orbit"/></label><label>Organization<select><option>acme-platform</option><option>side-projects</option></select></label><label>Daily budget<input value="$10"/></label></div>`}<footer><button onClick=${close}>Cancel</button>${step===2&&html`<${Action} primary=${true} onClick=${()=>{done('Agent attached to dev-mbp');close()}}>Attach agent</${Action}>`}</footer></div></${Dialog}>`}
function Header({onAttach}){return html`<header class="p-agents-head"><div><p>AGENT ROSTER</p><h1>Autonomy, with an accountable steward.</h1><span>One durable agent owns many conversations on a registered device.</span></div><${Action} primary=${true} onClick=${onAttach}><${Icon} name="plus"/> Attach agent</${Action}></header>`}
function AgentRows({agent,chosen,expanded,toggle,expand,toast}){const row=html`<tr><td><input aria-label=${`Select ${agent.id}`} type="checkbox" checked=${chosen} onChange=${toggle}/></td><td><button class="p-agents-name" onClick=${expand}><b>${agent.id}</b><small>${agent.org} · ${agent.model}</small></button></td><td><${StatusPill} status=${state(agent)}/></td><td><span>${agent.device}</span>${agent.reason&&html`<small class="p-agents-offline">${agent.reason}</small>`}</td><td>${agent.queue} runs</td><td>${agent.spend} <small>of ${agent.budget}</small></td><td><button class="p-agents-icon-button" onClick=${expand}>⌄</button></td></tr>`;const detail=expanded&&html`<tr class="p-agents-expand"><td colSpan="7"><div><span><b>Tools</b>${agent.tools}</span><span><b>Working directory</b>${agent.cwd}</span><span><b>Last audit</b>${agent.audit}</span><${Action} onClick=${()=>notify(toast,agent.status==='paused'?'Agent resumed':'Pause scheduled after current run')}>${agent.status==='paused'?'Resume':'Pause'}</${Action}></div></td></tr>`;return [row,detail]}
function DenseTable({toast}){const [chosen,setChosen]=useState([]),[expanded,setExpanded]=useState(null),[dialog,setDialog]=useState(false);const toggle=id=>setChosen(x=>x.includes(id)?x.filter(v=>v!==id):[...x,id]);return html`<section class="p-agents-layout"><${Header} onAttach=${()=>setDialog(true)}/><div class="p-agents-bulk"><label><input type="checkbox" checked=${chosen.length===agents.length} onChange=${()=>setChosen(chosen.length===agents.length?[]:agents.map(a=>a.id))}/> ${chosen.length||'No'} selected</label><button onClick=${()=>notify(toast,'Selected agents paused at checkpoint')}>Pause</button><button onClick=${()=>notify(toast,'Selected agents resumed')}>Resume</button><span>4 agents · 2 active queues</span></div><div class="p-agents-table-wrap"><table class="p-agents-table"><thead><tr><th></th><th>Agent / steward</th><th>Status</th><th>Device</th><th>Queue</th><th>Budget</th><th></th></tr></thead><tbody>${agents.map(a=>html`<${AgentRows} agent=${a} chosen=${chosen.includes(a.id)} expanded=${expanded===a.id} toggle=${()=>toggle(a.id)} expand=${()=>setExpanded(expanded===a.id?null:a.id)} toast=${toast}/>` )}</tbody></table></div>${dialog&&html`<${CreateDialog} close=${()=>setDialog(false)} done=${text=>notify(toast,text)}/>`}</section>`}
function Spark({values}){return html`<svg class="p-agents-spark" viewBox="0 0 120 34" aria-label="Seven day activity"><polyline points=${values.map((v,i)=>`${i*20},${32-v}`).join(' ')} fill="none" stroke="currentColor" stroke-width="2"/></svg>`}
function Roster({toast}){const [dialog,setDialog]=useState(false);const groups=['acme-platform','side-projects','oss-maintenance'];return html`<section class="p-agents-layout"><${Header} onAttach=${()=>setDialog(true)}/><div class="p-agents-roster-summary"><span><i></i> 2 online</span><span>1 paused</span><span>1 needs attention</span></div><div class="p-agents-roster">${groups.map(org=>html`<section><header><b>${org}</b><span>${agents.filter(a=>a.org===org).length} steward${agents.filter(a=>a.org===org).length>1?'s':''}</span></header><div>${agents.filter(a=>a.org===org).map(a=>html`<article class=${a.status}><div class="p-agents-card-top"><span class="p-agents-avatar">${a.id.slice(0,1).toUpperCase()}</span><div><h2>${a.id}</h2><${StatusPill} status=${state(a)}/></div><button aria-label=${`Open ${a.id}`} onClick=${()=>notify(toast,`${a.id} selected`)}><${Icon} name="arrow-up-right"/></button></div><p>${a.model} · ${a.device}</p><${Spark} values=${a.activity}/><div class="p-agents-card-meta"><span>${a.queue} queued</span><span>${a.spend} today</span></div>${a.reason&&html`<div class="p-agents-reason">${a.reason}</div>`}<footer>${a.capabilities.map(x=>html`<em>${x}</em>`)}</footer></article>`)}</div></section>`)}</div>${dialog&&html`<${CreateDialog} close=${()=>setDialog(false)} done=${text=>notify(toast,text)}/>`}</section>`}
function Detail({toast}){const [selected,setSelected]=useState(agents[0]),[tab,setTab]=useState('Overview'),[dialog,setDialog]=useState(false);return html`<section class="p-agents-detail"><header class="p-agents-detail-head"><div><p>AGENT WORKSPACE</p><h1>Steward configuration and live operating context.</h1></div><${Action} primary=${true} onClick=${()=>setDialog(true)}>Attach agent</${Action}></header><div class="p-agents-workspace"><aside class="p-agents-list"><b>STEWARDS</b>${agents.map(a=>html`<button class=${selected.id===a.id?'selected':''} onClick=${()=>{setSelected(a);setTab('Overview')}}><i class=${a.status}></i><span>${a.id}<small>${a.org}</small></span><small>${a.queue}</small></button>`)}</aside><section class="p-agents-inspect"><header><div><h2>${selected.id}</h2><span>${selected.device} · ${selected.model}</span></div><${StatusPill} status=${state(selected)}/></header><${Tabs} value=${tab} setValue=${setTab} items=${['Overview','Config','Conversations','Queue','Audit']}/><div class="p-agents-tab-body">${tab==='Overview'?html`<div class="p-agents-overview"><article><small>DAILY BUDGET</small><b>${selected.spend}</b><span>of ${selected.budget}</span></article><article><small>QUEUE DEPTH</small><b>${selected.queue}</b><span>conversations awaiting work</span></article><article><small>CAPABILITIES</small><p>${selected.capabilities.join(' · ')}</p></article><div class="p-agents-status-callout ${selected.status}"><b>${selected.status==='offline'?'Offline device':'Operating normally'}</b><p>${selected.reason||selected.audit}</p></div><${Action} onClick=${()=>notify(toast,selected.status==='paused'?'Agent resumed':'Pause scheduled after checkpoint')}>${selected.status==='paused'?'Resume agent':'Pause agent'}</${Action}></div>`:tab==='Config'?html`<form class="p-agents-config" onSubmit=${e=>{e.preventDefault();notify(toast,'Agent configuration saved')}}><label>Model<select><option>${selected.model}</option><option>Claude Haiku</option><option>GPT-4.1</option></select></label><label>Working directory<input value=${selected.cwd}/></label><label>Daily budget<input value=${selected.budget}/></label><label>Tool grants<input value=${selected.tools}/></label><button class="p-agents-action primary">Save configuration</button></form>`:tab==='Conversations'?html`<div class="p-agents-conversations">${conversations[selected.id].map((x,i)=>html`<article><i class=${i===0?'run':''}></i><span><b>${x}</b><small>${i===0?'Running now':'Last activity '+(i+8)+'m ago'}</small></span></article>`)}</div>`:tab==='Queue'?html`<div class="p-agents-queue"><b>${selected.queue} queued conversations</b><p>Concurrency limit: 3 · next checkpoint in 4 minutes.</p><button onClick=${()=>notify(toast,'Queue rebalanced')}>Rebalance queue</button></div>`:html`<div class="p-agents-audit">${audits.map(x=>html`<article><i></i><span>${x}<small>Today · Console</small></span></article>`)}</div>`}</div></section></div>${dialog&&html`<${CreateDialog} close=${()=>setDialog(false)} done=${text=>notify(toast,text)}/>`}</section>`}
export default function AgentsPage(){const [toast,setToast]=useState('');return html`<main class="e-page p-agents-page"><${PageVariants} variants=${[{key:'1',name:'Operations table',render:()=>html`<${DenseTable} toast=${setToast}/>`},{key:'2',name:'Organization roster',render:()=>html`<${Roster} toast=${setToast}/>`},{key:'3',name:'Agent workspace',render:()=>html`<${Detail} toast=${setToast}/>`}]}/><${Toast} text=${toast}/></main>`}
